##### 类模板：Array

```cpp
#include <iostream>
using namespace std;

template <typename T>
class Array {
public:
    Array() {
        data = new T[BLK_SIZE];
        next = nullptr ;
     }
    ~Array() {
        delete [] data;
        delete next;
     }
    T& operator[](int i);
    void iterate(void (*f)(T&));
private:
    T  *data; // data of type T
    static const int BLK_SIZE=32; // fixed block size
    Array *next;  // the next array block
};

template <typename T>
T& Array<T>::operator[](int i) {
    if (i < BLK_SIZE) {
        return data[i];
     } else {
        if (next == NULL) {
            next = new Array<T>;
         }
        return (*next)[i-BLK_SIZE];
    }
}

template <typename T>
void Array<T>::iterate(void (*f)(T&)) {
    for (int i = 0; i < BLK_SIZE; i++) {
        f(data[i]);
    }
    if (next != NULL) {
        next-> iterate(f);
    }
}

int main()
{
    Array<int> a;
    int size = 100;
    cin >> size;
    for (int i = 0; i < size; i++) {
        a[i] = i;
    }
    a.iterate([](int &x) { cout << x << endl; });
}
```

##### 函数模板：内积

此处的 `op`操作之前没有接触过，利用的是标准库提供的二元操作：

```cpp
#include <functional>
#include <iostream>
#include <vector>

template <class InputIt1, class InputIt2, class T, class BinaryOp1, class BinaryOp2>
T inner_product(InputIt1 first1, InputIt1 last1, InputIt2 first2, T init, BinaryOp1 op1, BinaryOp2 op2)
{
  while (first1 != last1)
  {
    init = op1 (init, op2(*first1, *first2) );
    ++first1;
	++first2;
  }
  return init;
}

int main()
{
  std::vector<int> a{0, 1, 2, 3, 4};
  std::vector<int> b{5, 4, 2, 3, 1};
  int r1 = inner_product(a.begin(), a.end(), b.begin(), 0, std::plus<>(), std::multiplies<>());
  std::cout << "Inner product of a and b: " << r1 << '\n';

  int r2 = inner_product(a.begin(), a.end(), b.begin(), 0, std::plus<>(), std::equal_to<>());
  std::cout << "Number of pairwise matches between a and b: " <<  r2 << '\n';
}

```

